const payload = $json.body ?? $json;

// Accept either a direct payload or:
// { event_type: "attachment.ready", data: {...} }
const input = payload.data ?? payload;

const eventType =
  payload.event_type ??
  input.event_type ??
  "attachment.ready";

if (
  eventType !== "attachment.ready" &&
  eventType !== "attachment_ready"
) {
  throw new Error(`Unsupported event type: ${eventType}`);
}

// -------------------------
// Required fields
// -------------------------

const requiredFields = [
  "job_id",
  "attachment_id",
  "external_order_id",
  "platform",
  "original_filename",
  "download_url"
];

for (const field of requiredFields) {
  if (
    input[field] === undefined ||
    input[field] === null ||
    String(input[field]).trim() === ""
  ) {
    throw new Error(`Missing required field: ${field}`);
  }
}

// -------------------------
// File number
// -------------------------

const fileNumber = Number(input.file_number ?? 1);

if (!Number.isInteger(fileNumber) || fileNumber < 1) {
  throw new Error("file_number must be a positive integer");
}

// -------------------------
// Download URL
// -------------------------

const downloadUrl = String(input.download_url).trim();

if (!/^https?:\/\/[^\s]+$/i.test(downloadUrl)) {
  throw new Error(
    `Invalid download_url: ${input.download_url}`
  );
}

// -------------------------
// Safe folder/file names
// -------------------------

function safeName(
  value,
  fallback = "unknown",
  maximumLength = 60
) {
  const cleaned = String(value ?? "")
    .normalize("NFKC")
    .trim()
    .replace(/[<>:"/\\|?*\x00-\x1F]/g, "-")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/[. ]+$/g, "")
    .replace(/^[-. ]+|[-. ]+$/g, "");

  return cleaned.substring(0, maximumLength) || fallback;
}

function strictIdentifier(
  value,
  fieldName,
  maximumLength = 50
) {
  const identifier = String(value ?? "")
    .trim()
    .toUpperCase();

  if (!identifier) {
    throw new Error(`Missing ${fieldName}`);
  }

  if (identifier.length > maximumLength) {
    throw new Error(
      `${fieldName} exceeds ${maximumLength} characters`
    );
  }

  if (!/^[A-Z0-9][A-Z0-9_-]*$/.test(identifier)) {
    throw new Error(
      `Invalid ${fieldName}: ${value}`
    );
  }

  return identifier;
}

// -------------------------
// Strict platform names
// -------------------------

const allowedPlatforms = new Set([
  "shopee",
  "lazada",
  "website",
  "whatsapp"
]);

const platform = String(input.platform)
  .trim()
  .toLowerCase();

if (!allowedPlatforms.has(platform)) {
  throw new Error(
    `Unsupported platform: ${input.platform}`
  );
}

// -------------------------
// Strict order information
// -------------------------

const testMode = input.test_mode === true;

const order = strictIdentifier(
  input.external_order_id,
  "external_order_id",
  40
);

const item = input.order_item_id
  ? strictIdentifier(
      input.order_item_id,
      "order_item_id",
      40
    )
  : "UNMATCHED";

if (
  !testMode &&
  /^(STRESS|LOAD|INVALID)[_-]/.test(order)
) {
  throw new Error(
    `Test order ID cannot be used in production mode: ${order}`
  );
}

// Prefer SKU because it is more stable than product name
const skuSource =
  input.sku ||
  input.product_name;

if (!skuSource) {
  throw new Error(
    "Either sku or product_name is required"
  );
}

const sku = safeName(
  skuSource,
  "UNMATCHED",
  40
).toUpperCase();

// -------------------------
// Original extension
// Finalize File Extension can correct it later
// using the downloaded MIME type.
// -------------------------

const originalFilename = safeName(
  input.original_filename,
  "attachment",
  100
);

const extensionMatch = originalFilename.match(
  /(\.[a-zA-Z0-9]{1,10})$/
);

const extension = extensionMatch
  ? extensionMatch[1].toLowerCase()
  : "";

// -------------------------
// Final paths
// -------------------------

const sequence = String(fileNumber).padStart(2, "0");

const rootFolder = testMode
  ? "_TESTS"
  : "Orders";

const relativeFolder =
  `${rootFolder}/${platform}/${order}/${item}_${sku}`;

const finalFilename =
  `${order}_${item}_${sku}_${sequence}${extension}`;

return [
  {
    json: {
      ...input,
      download_url: downloadUrl,
      event_type: "attachment.ready",
      test_mode: testMode,
      file_number: fileNumber,
      relative_folder: relativeFolder,
      final_filename: finalFilename,
      temporary_filename: `${finalFilename}.part`,
      relative_final_path:
        `${relativeFolder}/${finalFilename}`
    }
  }
];

const downloadedItem = $input.first();
const metadata = $("Prepare File Paths").first().json;
const binaryFile = downloadedItem.binary?.data;

if (!binaryFile) {
  throw new Error("Downloaded binary data is missing");
}

function getExtension(filename) {
  const match = String(filename || "")
    .toLowerCase()
    .match(/\.([a-z0-9]+)$/);

  return match ? match[1] : "";
}

function cleanExtension(extension) {
  return String(extension || "")
    .toLowerCase()
    .replace(/^\./, "")
    .replace(/[^a-z0-9]/g, "");
}

const mimeType = String(binaryFile.mimeType || "")
  .split(";")[0]
  .trim()
  .toLowerCase();

const originalExtension = getExtension(
  metadata.original_filename
);

const binaryExtension =
  cleanExtension(binaryFile.fileExtension) ||
  getExtension(binaryFile.fileName);

// Valid extensions for recognized MIME types.
// The first extension is the default.
const mimeExtensions = {
  "application/pdf": ["pdf"],
  "image/jpeg": ["jpg", "jpeg", "jpe"],
  "image/png": ["png"],
  "image/webp": ["webp"],
  "image/gif": ["gif"],
  "image/tiff": ["tif", "tiff"],
  "image/bmp": ["bmp"],
  "image/svg+xml": ["svg"],
  "text/plain": ["txt"],
  "application/zip": ["zip"],
  "application/x-zip-compressed": ["zip"],
  "application/vnd.adobe.photoshop": ["psd"]
};

const allowedExtensions = mimeExtensions[mimeType];

let finalExtension;

if (allowedExtensions) {
  // Preserve .jpeg instead of changing it to .jpg when valid.
  if (allowedExtensions.includes(originalExtension)) {
    finalExtension = originalExtension;
  } else if (allowedExtensions.includes(binaryExtension)) {
    finalExtension = binaryExtension;
  } else {
    finalExtension = allowedExtensions[0];
  }
} else {
  // AI, PSD and other design files may use a generic MIME type.
  finalExtension =
    binaryExtension ||
    originalExtension ||
    "bin";
}

const filenameWithoutExtension =
  metadata.final_filename.replace(/\.[a-z0-9]+$/i, "");

const finalFilename =
  `${filenameWithoutExtension}.${finalExtension}`;

return [
  {
    json: {
      ...metadata,
      downloaded_mime_type: mimeType,
      original_extension: originalExtension,
      detected_extension: finalExtension,
      extension_changed:
        Boolean(originalExtension) &&
        originalExtension !== finalExtension,
      final_filename: finalFilename,
      temporary_filename: `${finalFilename}.part`,
      relative_final_path:
        `${metadata.relative_folder}/${finalFilename}`
    },
    binary: downloadedItem.binary
  }
];
